/**
 * Phase 18 W5b acceptance 2 (docs/specs/phase-18-open-world-foods.md): the fixed keep-local corpus
 * for the taste safety check (lib/profile/taste-safety.ts). Every sentence here must stay on the
 * phone (`route: "local"`) and reach Jev 0 times — no false negative is allowed. Add a sentence the
 * moment one is found that the check would send; never remove one.
 *
 * `reason` is the reason the check must give. PLAIN holds sentences that must be sent.
 */
import type { TasteLocalReason } from "@/lib/profile/taste-safety";
import REDTEAM from "@/tests/fixtures/taste-safety-redteam.json";

export type CorpusCase = { text: string; reason: TasteLocalReason };

const rules = (text: string): CorpusCase => ({ text, reason: "rules" });
const symptom = (text: string): CorpusCase => ({ text, reason: "symptom" });
const unsure = (text: string): CorpusCase => ({ text, reason: "unsure" });

/** The acceptance 2 examples, verbatim. */
export const ACCEPTANCE_LOCAL: readonly CorpusCase[] = [
  rules("I'm allergic to peanuts"),
  rules("I have celiac"),
  rules("I keep kosher"),
  rules("my doctor says no grapefruit"),
  symptom("soft food makes me vomit"),
  symptom("dairy gives me cramps"),
  symptom("beans make me bloated"),
  symptom("I get a rash after strawberries"),
  symptom("spicy food doesn't agree with me"),
  symptom("eggs upset my stomach"),
  unsure(`${"I like a lot of different things and I have been thinking about what I eat for a long "
    + "while now, mostly about the textures and the flavors I grew up with at home, and how they "
    + "changed after I moved away to a new city where the food is very different from home."}`.slice(0, 250)),
  unsure("I can't do blorp anymore"),
];

